package vn.eduassistant.backend.web;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import vn.eduassistant.backend.config.AppConfig;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;

@RestController
public class AdminController {
    private final AuthService auth;private final JdbcSupport db;private final UserService users;private final AuditService audits;private final PolicyService policy;private final AppConfig config;private final RedisSupport redis;
    public AdminController(AuthService auth,JdbcSupport db,UserService users,AuditService audits,PolicyService policy,AppConfig config,RedisSupport redis){this.auth=auth;this.db=db;this.users=users;this.audits=audits;this.policy=policy;this.config=config;this.redis=redis;}
    @GetMapping("/api/sis/me") public ResponseEntity<?> mySis(HttpServletRequest req){Map<String,Object>u=auth.require(req,"ADMIN"),record=db.one("SELECT studentcode AS \"studentCode\",fullname AS \"fullName\",academicstatus AS \"academicStatus\",coursestartdate AS \"courseStartDate\",courseenddate AS \"courseEndDate\",currenttermactive AS \"currentTermActive\",hascurrentschedule AS \"hasCurrentSchedule\",registeredpermanentaddress AS \"registeredPermanentAddress\",faculty,source,recordstatus AS \"recordStatus\",updatedat AS \"updatedAt\" FROM sis_student_records WHERE userid=?",u.get("id"));return ApiResponse.success(200,"SIS record loaded.",UserService.map("record",record));}
    @GetMapping("/api/admin/policies") public ResponseEntity<?> policies(HttpServletRequest req){auth.require(req,"ADMIN");Map<String,Object> state=db.one("SELECT * FROM escalation_policy_state WHERE id='GLOBAL_NVQS_POLICY'");List<Map<String,Object>>history=db.all("SELECT * FROM escalation_threshold_history ORDER BY createdat DESC LIMIT 10");return ApiResponse.success(200,"Policy registry loaded.",UserService.map("policies",policyRegistry(),"domain","MILITARY_SERVICE_CONFIRMATION","adaptivePolicy",state,"thresholdHistory",history));}
    @GetMapping("/api/admin/sis") public ResponseEntity<?> listSis(@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="")String academicStatus,@RequestParam(defaultValue="")String faculty,@RequestParam(defaultValue="")String recordStatus,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int pageSize,HttpServletRequest req){auth.require(req,"ADMIN");StringBuilder w=new StringBuilder(" WHERE 1=1");List<Object>a=new ArrayList<Object>();if(!search.trim().isEmpty()){w.append(" AND (studentcode ILIKE ? OR fullname ILIKE ? OR faculty ILIKE ? OR registeredpermanentaddress ILIKE ?)");String q="%"+search.trim()+"%";for(int i=0;i<4;i++)a.add(q);}for(String[]pair:new String[][]{{"academicstatus",academicStatus},{"faculty",faculty},{"recordstatus",recordStatus}})if(!pair[1].trim().isEmpty()){w.append(" AND ").append(pair[0]).append("=?");a.add(pair[1].trim());}long total=db.count("SELECT COUNT(*) FROM sis_student_records"+w,a.toArray());int size=Math.max(1,Math.min(20,pageSize)),p=Math.max(1,page);List<Map<String,Object>> records=db.all("SELECT * FROM sis_student_records"+w+" ORDER BY updatedat DESC LIMIT ? OFFSET ?",append(a.toArray(),size,(p-1)*size));return ApiResponse.success(200,"SIS records loaded.",UserService.map("records",records,"total",total,"page",p,"pageSize",size));}
    @GetMapping("/api/admin/sis/available-students") public ResponseEntity<?> availableSis(HttpServletRequest req){auth.require(req,"ADMIN");List<Map<String,Object>> list=db.all("SELECT u.id,u.studentcode AS \"studentCode\",u.fullname AS \"fullName\",u.faculty,u.academicstatus AS \"academicStatus\" FROM users u LEFT JOIN sis_student_records s ON s.userid=u.id WHERE u.role='STUDENT' AND s.id IS NULL ORDER BY u.fullname");return ApiResponse.success(200,"Students available for SIS registration loaded.",UserService.map("students",list));}
    @PostMapping("/api/admin/sis") public ResponseEntity<?> createSis(@RequestBody Map<String,Object>b,HttpServletRequest req){Map<String,Object>u=auth.require(req,"ADMIN");String userId=Json.str(b.get("userId"));Map<String,Object>student=db.one("SELECT * FROM users WHERE id=? AND role='STUDENT'",userId);if(student==null)return ApiResponse.failure(400,false,"Select an existing student account for this SIS record.",null,"INVALID_STUDENT");if(db.one("SELECT id FROM sis_student_records WHERE userid=?",userId)!=null)return ApiResponse.failure(409,false,"This student already has an SIS record.",null,"SIS_RECORD_EXISTS");Map<String,Object>d=validateSis(b,student,true);if(d.containsKey("error"))return ApiResponse.failure((int)d.get("status"),false,Json.str(d.get("error")),null,Json.str(d.get("code")));String id="SIS-"+userId,now=Instant.now().toString();db.update("INSERT INTO sis_student_records(id,userid,studentcode,fullname,academicstatus,coursestartdate,courseenddate,currenttermactive,hascurrentschedule,registeredpermanentaddress,faculty,source,sourcetype,verificationstatus,recordstatus,createdat,updatedat,updatedby) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,userId,d.get("studentCode"),d.get("fullName"),d.get("academicStatus"),d.get("courseStartDate"),d.get("courseEndDate"),d.get("currentTermActive"),d.get("hasCurrentSchedule"),d.get("registeredPermanentAddress"),d.get("faculty"),"INTERNAL_SIS_ADMIN","INTERNAL_DEMO_SIS","UNVERIFIED",first(Json.str(d.get("recordStatus")),"ACTIVE"),now,now,u.get("id"));Map<String,Object>record=db.one("SELECT * FROM sis_student_records WHERE id=?",id);audits.log("ADMIN_SIS_RECORD_CREATED",u,UserService.map("recordId",id,"userId",userId,"studentCode",d.get("studentCode")),"SUCCESS","Admin created an unverified record in the internal demo SIS registry.");return ApiResponse.success(201,"SIS record created.",UserService.map("record",record));}
    @GetMapping("/api/admin/sis/{recordId}") public ResponseEntity<?> getSis(@PathVariable String recordId,HttpServletRequest req){auth.require(req,"ADMIN");Map<String,Object>r=db.one("SELECT * FROM sis_student_records WHERE id=?",recordId);return r==null?ApiResponse.failure(404,false,"SIS record not found.",null,"NOT_FOUND"):ApiResponse.success(200,"SIS record loaded.",UserService.map("record",r));}
    @PutMapping("/api/admin/sis/{recordId}") public ResponseEntity<?> updateSis(@PathVariable String recordId,@RequestBody Map<String,Object>b,HttpServletRequest req){Map<String,Object>u=auth.require(req,"ADMIN"),old=db.one("SELECT * FROM sis_student_records WHERE id=?",recordId);if(old==null)return ApiResponse.failure(404,false,"SIS record not found.",null,"NOT_FOUND");Map<String,Object>d=validateSis(b,old,false);if(d.containsKey("error"))return ApiResponse.failure((int)d.get("status"),false,Json.str(d.get("error")),null,Json.str(d.get("code")));if(d.get("studentCode")!=null&&db.one("SELECT id FROM sis_student_records WHERE studentcode=? AND id<>?",d.get("studentCode"),recordId)!=null)return ApiResponse.failure(409,false,"Student code already exists.",null,"DUPLICATE_STUDENT_CODE");String now=Instant.now().toString();Map<String,Object>changed=new LinkedHashMap<String,Object>();for(String k:d.keySet())if(!Objects.equals(old.get(k),d.get(k)))changed.put(k,UserService.map("old",old.get(k),"new",d.get(k)));if(!changed.isEmpty()){db.update("UPDATE sis_student_records SET studentcode=?,fullname=?,academicstatus=?,coursestartdate=?,courseenddate=?,currenttermactive=?,hascurrentschedule=?,registeredpermanentaddress=?,faculty=?,recordstatus=?,verificationstatus='UNVERIFIED',verifiedby=NULL,verifiedat=NULL,updatedat=?,updatedby=? WHERE id=?",d.get("studentCode"),d.get("fullName"),d.get("academicStatus"),d.get("courseStartDate"),d.get("courseEndDate"),d.get("currentTermActive"),d.get("hasCurrentSchedule"),d.get("registeredPermanentAddress"),d.get("faculty"),d.get("recordStatus"),now,u.get("id"),recordId);audits.log("ADMIN_SIS_RECORD_UPDATED",u,UserService.map("recordId",recordId,"studentCode",d.get("studentCode"),"changedFields",changed),"SUCCESS","Admin edited internal demo SIS facts; any previous demo verification was cleared.");}return ApiResponse.success(200,"SIS record updated.",UserService.map("record",db.one("SELECT * FROM sis_student_records WHERE id=?",recordId)));}
    @PostMapping("/api/admin/sis/{recordId}/verify-demo") public ResponseEntity<?> verifySis(@PathVariable String recordId,@RequestBody(required=false)Map<String,Object>b,HttpServletRequest req){Map<String,Object>u=auth.require(req,"ADMIN"),r=db.one("SELECT * FROM sis_student_records WHERE id=?",recordId);if(r==null)return ApiResponse.failure(404,false,"SIS record not found.",null,"NOT_FOUND");if(!"INTERNAL_DEMO_SIS".equals(r.get("sourceType")))return ApiResponse.failure(400,false,"Only internal demo SIS records can receive demo verification.",null,"INVALID_SIS_SOURCE");String now=Instant.now().toString(),reason=b==null?"":Json.str(b.get("reason"));if(reason.trim().isEmpty())reason="Admin confirmed this internal record for the EDUASSISTANT demo workflow; this does not verify data against a university SIS.";db.update("UPDATE sis_student_records SET verificationstatus='ADMIN_VERIFIED_DEMO',verifiedby=?,verifiedat=?,updatedat=?,updatedby=? WHERE id=?",u.get("id"),now,now,u.get("id"),recordId);audits.log("ADMIN_SIS_RECORD_VERIFIED_DEMO",u,UserService.map("recordId",recordId,"studentCode",r.get("studentCode"),"oldVerificationStatus",r.get("verificationStatus"),"newVerificationStatus","ADMIN_VERIFIED_DEMO","verifiedAt",now,"reason",reason),"SUCCESS",reason);return ApiResponse.success(200,"Internal SIS record marked as verified for demo use.",UserService.map("record",db.one("SELECT * FROM sis_student_records WHERE id=?",recordId)));}
    @GetMapping("/api/admin/users") public ResponseEntity<?> listUsers(HttpServletRequest req){auth.require(req,"ADMIN");Map<String,Object>identity=UserService.map("view","all-users");Object cached=redis.getJson("admin-users",identity);if(cached instanceof Map)return ApiResponse.success(200,"Cached users.",cached);List<Map<String,Object>>all=users.users();Map<String,Object>data=UserService.map("users",all,"total",all.size());redis.setJson("admin-users",identity,data,20);return ApiResponse.success(200,"Lấy danh sách người dùng thành công.",data);}
    @PostMapping("/api/admin/users/create") public ResponseEntity<?> createUser(@RequestBody Map<String,Object>b,HttpServletRequest req){Map<String,Object>actor=auth.require(req,"ADMIN");String username=Json.str(b.get("username")).trim(),password=Json.str(b.get("password"));if(username.isEmpty()||password.length()<6)return ApiResponse.failure(400,false,"Tên đăng nhập và mật khẩu (tối thiểu 6 ký tự) là bắt buộc.",null,"VALIDATION_ERROR");if(users.userByUsername(username)!=null)return ApiResponse.failure(409,false,"Tên đăng nhập này đã được sử dụng.",null,"USERNAME_EXISTS");Map<String,Object>created=users.create(b,actor);if("STUDENT".equals(created.get("role"))){String now=Instant.now().toString();db.update("UPDATE sis_student_records SET currenttermactive=FALSE,hascurrentschedule=FALSE,updatedby=? WHERE userid=?",actor.get("id"),created.get("id"));audits.log("ADMIN_SIS_RECORD_PROVISIONED",actor,UserService.map("userId",created.get("id"),"recordId","SIS-"+created.get("id"),"studentCode",created.get("studentCode")),"SUCCESS","A blank SIS record was provisioned automatically with the new student account.");}Map<String,Object>clean=JdbcSupport.copyWithout(created,"password","twoFactorSecret");Map<String,Object>out=new LinkedHashMap<String,Object>();out.put("user",clean);out.putAll(clean);return ApiResponse.success(201,"Tạo tài khoản "+b.get("fullName")+" ("+b.get("role")+") thành công.",out);}
    @PutMapping("/api/admin/users/{userId}/role") public ResponseEntity<?> updateRole(@PathVariable String userId,@RequestBody Map<String,Object>b,HttpServletRequest req){Map<String,Object>actor=auth.require(req,"ADMIN");String role=Json.str(b.get("role"));if(!Arrays.asList("STUDENT","REVIEWER","ADMIN").contains(role))return ApiResponse.failure(400,false,"Vai trò không hợp lệ. Chỉ chấp nhận STUDENT, REVIEWER, ADMIN.",null,"INVALID_ROLE");Map<String,Object>target=users.userById(userId);if(target==null)return ApiResponse.failure(404,false,"Không tìm thấy người dùng.",null,"NOT_FOUND");db.update("UPDATE users SET role=?,updatedat=? WHERE id=?",role,Instant.now().toString(),userId);audits.log("ADMIN_ROLE_UPDATED",actor,UserService.map("userId",userId,"oldRole",target.get("role"),"newRole",role),"SUCCESS","Quản trị viên thay đổi vai trò người dùng.");return ApiResponse.success(200,"Cập nhật vai trò sang "+role+" thành công.",JdbcSupport.copyWithout(users.userById(userId),"password","twoFactorSecret"));}
    @GetMapping({"/api/admin/users/export-csv","/api/admin/users/export"}) public ResponseEntity<byte[]> exportUsers(HttpServletRequest req){auth.require(req,"ADMIN");StringBuilder c=new StringBuilder("\uFEFFID,Username,Full name,Role,Student code,Email,Department\r\n");for(Map<String,Object>u:users.users()){Object[]v={u.get("id"),u.get("username"),u.get("fullName"),u.get("role"),u.get("studentCode"),u.get("email"),u.get("department")};appendCsv(c,v);}return csvResponse(c,"EDUASSISTANT_Nguoi_Dung_");}
    @GetMapping({"/api/admin/stats","/api/admin/system/metrics"}) public ResponseEntity<?> stats(HttpServletRequest req){auth.require(req,"ADMIN");Map<String,Object>usersCount=db.one("SELECT COUNT(*) AS total FROM users"),caseCounts=db.one("SELECT COUNT(*) AS total,COUNT(*) FILTER(WHERE status IN ('SUBMITTED','UNDER_REVIEW','REQUIRES_SUPPLEMENT')) AS pending,COUNT(*) FILTER(WHERE status='APPROVED') AS approved,COUNT(*) FILTER(WHERE status='REJECTED') AS rejected,COUNT(*) FILTER(WHERE createdat LIKE ?) AS today FROM cases",LocalDate.now(java.time.ZoneOffset.UTC).toString()+"%"),auditCounts=db.one("SELECT COUNT(*) AS total,COUNT(*) FILTER(WHERE action='HUMAN_OVERRIDE') AS overrides,COUNT(*) FILTER(WHERE action='REVIEWER_FEEDBACK_SUBMITTED') AS feedback FROM audits");List<Map<String,Object>>statusRows=db.all("SELECT status,COUNT(*) AS count FROM cases GROUP BY status");List<Map<String,Object>>roleRows=db.all("SELECT role,COUNT(*) AS count FROM users GROUP BY role");List<Map<String,Object>>categoryRows=db.all("SELECT category,COUNT(*) AS count FROM cases GROUP BY category");List<Map<String,Object>>priorityRows=db.all("SELECT priority,COUNT(*) AS count FROM cases GROUP BY priority");List<Map<String,Object>>recent=db.all("SELECT * FROM cases ORDER BY createdat DESC LIMIT 10");Map<String,Object>statusMap=group(statusRows,"status"),roleMap=group(roleRows,"role"),categoryMap=group(categoryRows,"category"),priorityMap=group(priorityRows,"priority");long total=number(caseCounts,"total"),approved=number(caseCounts,"approved"),uploads=0,size=0;String uploadDir=AppConfig.value("DATA_DIR","");java.nio.file.Path up=java.nio.file.Paths.get(uploadDir==null||uploadDir.isEmpty()?System.getProperty("user.dir"):uploadDir,"uploads");try{if(java.nio.file.Files.exists(up))try(java.util.stream.Stream<java.nio.file.Path>s=java.nio.file.Files.list(up)){java.util.Iterator<java.nio.file.Path>it=s.iterator();while(it.hasNext()){java.nio.file.Path p=it.next();if(java.nio.file.Files.isRegularFile(p)){uploads++;size+=java.nio.file.Files.size(p);}}}}catch(Exception ignored){}Map<String,Object>benchmark=UserService.map("decisionAccuracy","Not measured yet","missedEscalationRate","Not measured yet","unnecessaryEscalationRate","Not measured yet","automationRate","Not measured yet","lastBenchmarkRun",null);Map<String,Object>result=UserService.map("totalUsers",number(usersCount,"total"),"totalCases",total,"todayCasesCount",number(caseCounts,"today"),"pendingCases",number(caseCounts,"pending"),"approvedCases",approved,"rejectedCases",number(caseCounts,"rejected"),"approvalRate",total==0?0:Math.round(approved*100.0/total),"statusBreakdown",statusMap,"categoryBreakdown",categoryMap,"priorityBreakdown",priorityMap,"roleBreakdown",roleMap,"autoApprovedCases",approved,"escalatedCases",number(caseCounts,"pending"),"escalationReasonsBreakdown",Collections.emptyMap(),"recentCases",recent,"totalAudits",number(auditCounts,"total"),"totalUploads",uploads,"uploadStorageSizeMB",Math.round(size/10485.76)/100.0,"aiMode",config.aiMode,"systemStatus","ONLINE","currentEscalationThreshold",policy.threshold(),"totalHumanOverrides",number(auditCounts,"overrides"),"totalReviewerFeedback",number(auditCounts,"feedback"),"missedEscalationFeedbackCount",0,"unnecessaryEscalationFeedbackCount",0,"correctFeedbackCount",0,"benchmarkMetrics",benchmark,"serverTime",Instant.now().toString());return ApiResponse.success(200,"Lấy chỉ số hệ thống thành công.",result);}
    private Map<String,Object> validateSis(Map<String,Object>b,Map<String,Object> fallback,boolean create){Map<String,Object>d=new LinkedHashMap<String,Object>();String code=Json.str(b.get("studentCode")).trim();if(code.isEmpty())code=Json.str(fallback.get("studentCode"));String name=Json.str(b.get("fullName")).trim();if(name.isEmpty())return UserService.map("error","Full name is required.","status",400,"code","VALIDATION_ERROR");String academic=Json.str(b.get("academicStatus"));if(!academic.isEmpty()&&!Arrays.asList("ACTIVE","SUSPENDED","WITHDRAWN","GRADUATED","LEAVE_OF_ABSENCE","UNKNOWN").contains(academic))return UserService.map("error","Invalid academic status.","status",400,"code","VALIDATION_ERROR");String start=Json.str(b.get("courseStartDate")),end=Json.str(b.get("courseEndDate"));try{LocalDate a=start.isEmpty()?null:LocalDate.parse(start),z=end.isEmpty()?null:LocalDate.parse(end);if(a!=null&&z!=null&&a.isAfter(z))return UserService.map("error","Course start must not be after course end.","status",400,"code","VALIDATION_ERROR");}catch(Exception e){return UserService.map("error","Course dates must use YYYY-MM-DD.","status",400,"code","VALIDATION_ERROR");}d.put("studentCode",code.isEmpty()?null:code.toUpperCase());d.put("fullName",name);d.put("academicStatus",academic.isEmpty()?null:academic);d.put("courseStartDate",empty(b.get("courseStartDate")));d.put("courseEndDate",empty(b.get("courseEndDate")));d.put("currentTermActive",b.get("currentTermActive"));d.put("hasCurrentSchedule",b.get("hasCurrentSchedule"));d.put("registeredPermanentAddress",empty(b.get("registeredPermanentAddress")));d.put("faculty",empty(b.get("faculty")));d.put("recordStatus",first(Json.str(b.get("recordStatus")),create?"ACTIVE":Json.str(fallback.get("recordStatus"))));return d;}
    private static List<Map<String,Object>> policyRegistry(){return Arrays.asList(UserService.map("id","POL-NVQS-001","domain","MILITARY_SERVICE_CONFIRMATION","name","Identity ownership verification","ruleCode","RULE_SEC_01_OWNERSHIP_MISMATCH","systemAction","ESCALATE_TO_HUMAN","escalationReason","OWNERSHIP_UNCLEAR","status","ACTIVE"),UserService.map("id","POL-NVQS-002","domain","MILITARY_SERVICE_CONFIRMATION","name","Exception request outside workflow","ruleCode","RULE_POLICY_01_SPECIAL_EXCEPTION_REQUEST","systemAction","ESCALATE_TO_HUMAN","escalationReason","POLICY_OUT_OF_SCOPE","status","ACTIVE"));}
    private static Map<String,Object> group(List<Map<String,Object>>rows,String key){Map<String,Object>m=new LinkedHashMap<String,Object>();for(Map<String,Object>r:rows)m.put(Json.str(r.get(key)),r.get("count"));return m;}
    private static long number(Map<String,Object>m,String k){Object o=m.get(k);return o instanceof Number?((Number)o).longValue():0;}
    private static Object empty(Object o){String v=Json.str(o).trim();return v.isEmpty()?null:v;}
    private static String first(String a,String b){return a==null||a.trim().isEmpty()?b:a;}
    private static Object[] append(Object[]a,Object...b){Object[]x=Arrays.copyOf(a,a.length+b.length);System.arraycopy(b,0,x,a.length,b.length);return x;}
    private static void appendCsv(StringBuilder c,Object[]v){for(int i=0;i<v.length;i++){if(i>0)c.append(',');c.append('"').append(String.valueOf(v[i]==null?"":v[i]).replace("\"","\"\"")).append('"');}c.append("\r\n");}
    private static ResponseEntity<byte[]> csvResponse(StringBuilder c,String file){HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.parseMediaType("text/csv; charset=UTF-8"));h.setContentDisposition(ContentDisposition.attachment().filename(file+System.currentTimeMillis()+".csv").build());return new ResponseEntity<byte[]>(c.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),h,HttpStatus.OK);}
}
